00409         if (preg_match('/[\s"&|<>^()]/', $arg)) {
00410             // Escape any internal quotes by doubling them (Windows convention for cmd.exe/WScript.Shell)
00411             $escaped = str_replace('"', '""', $arg);
00412             return '"' . $escaped . '"';
